I optimized your implementations in case they get accepted:

```cs
public static void Fill<T>(this IList<T> list, T value)
{
    if (list is T[] array)
    {
        Array.Fill(array, value);
        return;
    }
    if (list is List<T> standardList)
    {
        CollectionsMarshal.AsSpan(standardList).Fill(value);
        return;
    }

    int listCount = list.Count;

    for (int i = 0; i < listCount; i++)
    {
        list[i] = value;
    }
}
public static T PickRandom<T>(this IList<T> list)
{
    int listCount = list.Count;

    if (listCount == 0)
    {
        return default!;
    }
    if (listCount == 1)
    {
        return list[0];
    }

    return list[GD.RandRange(0, listCount - 1)];
}
```

